ValidationRule.errorConditionFormula:
AND(
    DATEVALUE(CreatedDate) >= DATE(2025, 2, 1),
    OR(
        AND(
            ISBLANK(TEXT(New_CS_task_list__c)),
            NOT(ISBLANK(CS_TaskDateTime__c))
        ),
        AND(
            NOT(ISBLANK(TEXT(New_CS_task_list__c))),
            ISBLANK(CS_TaskDateTime__c)
        )
    )
)
